import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const [status, setStatus] = useState([]);
  const [result, setResult] = useState(null);

  const pushStatus = (msg) => setStatus(prev => [...prev, msg]);

  useEffect(() => {
    const startCamera = async () => {
      try {
        pushStatus("🎥 Démarrage de la caméra...");
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user", width: 640, height: 480 }
        });
        streamRef.current = stream;
        if (videoRef.current) videoRef.current.srcObject = stream;
        pushStatus("✅ Caméra démarrée avec succès");

        // Intervalle pour envoyer des frames toutes les 2 secondes
        let count = 0;
        const intervalId = setInterval(async () => {
          count += 2;
          pushStatus(`📸 Capture automatique à ${count}s...`);

          const canvas = document.createElement("canvas");
          canvas.width = videoRef.current.videoWidth || 640;
          canvas.height = videoRef.current.videoHeight || 480;
          const ctx = canvas.getContext("2d");
          ctx.drawImage(videoRef.current, 0, 0);
          const imageBase64 = canvas.toDataURL("image/jpeg", 0.8);

          try {
            const response = await attendanceAPI.recognize(imageBase64);
            const data = response?.data || {};
            if (data.success) {
              pushStatus(`✅ Reconnu: ${data.student} (${(data.confidence*100).toFixed(1)}%)`);
              setResult({
                name: data.student,
                confidence: (data.confidence*100).toFixed(1),
                studentId: data.student_id,
                time: new Date().toLocaleTimeString()
              });
            } else {
              pushStatus(`⚠️ Non reconnu (confiance ${(data.confidence*100).toFixed(1)}%)`);
            }
          } catch (err) {
            pushStatus(`❌ Erreur backend: ${err.message}`);
          }
        }, 2000);

        // Arrêter après 7 secondes
        setTimeout(() => {
          clearInterval(intervalId);
          if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
          }
          pushStatus("📴 Caméra arrêtée après 7 secondes");
        }, 7000);

      } catch (err) {
        pushStatus("❌ Impossible d'accéder à la caméra");
        console.error(err);
      }
    };

    startCamera();
  }, []);

  return (
    <div style={{ padding: 30, maxWidth: 900, margin: "auto", textAlign: "center" }}>
      <h2>📷 Reconnaissance Faciale - Détection continue (7s)</h2>
      <video ref={videoRef} autoPlay playsInline muted style={{ width: "100%", borderRadius: "12px" }} />
      <div style={{ marginTop: 20, textAlign: "left", background: "#F3F4F6", padding: 15, borderRadius: 10 }}>
        {status.map((s, i) => <div key={i}>{s}</div>)}
      </div>
      {result && (
        <div style={{ marginTop: 20, background: "#E0E7FF", padding: 15, borderRadius: 10 }}>
          <h3>✅ Étudiant reconnu</h3>
          <p><b>Nom:</b> {result.name}</p>
          <p><b>Confiance:</b> {result.confidence}%</p>
          <p><b>ID:</b> {result.studentId}</p>
          <p><b>Heure:</b> {result.time}</p>
        </div>
      )}
    </div>
  );
};

export default CameraRecognition;
